import * as THREE from './vendor/three.module.js';
export function createScene(container){
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(50,1,.1,100);camera.position.set(0,2,12);camera.lookAt(0,0,0);
const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));container.append(renderer.domElement);
scene.add(new THREE.AmbientLight(0xb8d7ee,2));const light=new THREE.DirectionalLight(0xc4f582,4);light.position.set(2,5,4);scene.add(light);
const stars=new THREE.BufferGeometry(),positions=[];for(let i=0;i<650;i++)positions.push((Math.random()-.5)*55,(Math.random()-.5)*28,-Math.random()*35);stars.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));scene.add(new THREE.Points(stars,new THREE.PointsMaterial({color:0xb9d5df,size:.035,transparent:true,opacity:.8})));
const orbitMaterial=new THREE.LineBasicMaterial({color:0x396175,transparent:true,opacity:.25});for(let r=3;r<=7;r+=1.8){const points=[];for(let i=0;i<=128;i++){const a=i/128*Math.PI*2;points.push(new THREE.Vector3(Math.cos(a)*r,Math.sin(a)*r*.4,0));}const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),orbitMaterial);line.position.y=-.4;scene.add(line);}
const ship=new THREE.Group();const body=new THREE.Mesh(new THREE.ConeGeometry(.24,1.2,4),new THREE.MeshStandardMaterial({color:0xd4e3e6,metalness:.65,roughness:.3}));body.rotation.x=-Math.PI/2;ship.add(body);const wings=new THREE.Mesh(new THREE.ConeGeometry(.6,.65,3),new THREE.MeshStandardMaterial({color:0x46737b,metalness:.7,roughness:.4}));wings.rotation.x=-Math.PI/2;wings.scale.z=.22;wings.position.z=.22;ship.add(wings);const engine=new THREE.Mesh(new THREE.ConeGeometry(.13,.65,12),new THREE.MeshBasicMaterial({color:0xc4f582,transparent:true,opacity:.9}));engine.rotation.x=Math.PI/2;engine.position.z=.85;ship.add(engine);ship.position.set(0,-2.05,1);scene.add(ship);
const enemy=new THREE.Group();const core=new THREE.Mesh(new THREE.IcosahedronGeometry(.35,0),new THREE.MeshStandardMaterial({color:0x90bd9c,metalness:.7,roughness:.3,wireframe:true}));enemy.add(core);const ring=new THREE.Mesh(new THREE.TorusGeometry(.58,.015,6,60),new THREE.MeshBasicMaterial({color:0x8dcbb3}));ring.rotation.x=.7;enemy.add(ring);enemy.position.set(0,1.9,-1);scene.add(enemy);
const particles=[];let shot=0;const beam=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,5,8),new THREE.MeshBasicMaterial({color:0xd8ff9f,transparent:true,opacity:0}));beam.position.set(0,0,0);scene.add(beam);
function resize(){const {width,height}=container.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(container);resize();const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function animate(t){requestAnimationFrame(animate);if(!document.hidden){if(!reduced){ship.rotation.z=Math.sin(t*.001)*.08;ship.position.x=Math.sin(t*.0006)*.3;core.rotation.y=t*.0007;ring.rotation.z=t*.0003;engine.scale.y=1+Math.sin(t*.025)*.15;}beam.material.opacity=Math.max(0,1-(t-shot)/280);for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.mesh.position.add(p.velocity);p.mesh.material.opacity-=.025;if(p.mesh.material.opacity<=0){scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();particles.splice(i,1);}}renderer.render(scene,camera);}}requestAnimationFrame(animate);
return {shoot(){shot=performance.now();for(let i=0;i<18;i++){const mesh=new THREE.Mesh(new THREE.IcosahedronGeometry(.035),new THREE.MeshBasicMaterial({color:i%2?0xc4f582:0x79d8e0,transparent:true}));mesh.position.copy(enemy.position);scene.add(mesh);particles.push({mesh,velocity:new THREE.Vector3((Math.random()-.5)*.08,(Math.random()-.5)*.08,(Math.random()-.5)*.08)});}}};}
